import json, os, glob

# Scan all experiment result files
result_files = sorted(glob.glob('results/*/exp*_results.json'))
result_files += sorted(glob.glob('results/*/results.json'))
result_files += sorted(glob.glob('results/cross_model_experiment/cross_model_results.json'))

for f in result_files:
    try:
        with open(f) as fh:
            data = json.load(fh)

        # Get summary info
        summary = data.get('summary', {})
        n = summary.get('n_problems', '?')
        sc = summary.get('sc_accuracy', summary.get('sc_acc', '?'))
        sica = summary.get('sica_accuracy', summary.get('sica_acc', '?'))

        # Count b, c from per-problem data
        results = data.get('results', [])
        per_problem = data.get('per_problem', {})

        b, c = 0, 0
        n_problems = 0
        if results:
            for r in results:
                sc_c = r.get('sc_correct')
                sica_c = r.get('sica_correct')
                if sc_c is not None and sica_c is not None:
                    n_problems += 1
                    if sc_c and not sica_c:
                        b += 1
                    elif not sc_c and sica_c:
                        c += 1
        elif per_problem:
            for pid, r in per_problem.items():
                sc_c = r.get('sc_correct')
                sica_c = r.get('sica_correct')
                if sc_c is not None and sica_c is not None:
                    n_problems += 1
                    if sc_c and not sica_c:
                        b += 1
                    elif not sc_c and sica_c:
                        c += 1

        if n_problems > 0:
            delta = (c - b) / n_problems * 100
            print(f'{f}: n={n_problems}, SC={sc}, SICA={sica}, b={b}, c={c}, delta={delta:+.1f}pp')
    except Exception as e:
        print(f'{f}: ERROR: {e}')
"

